package io.xeros.content.bosses;
import io.xeros.content.instances.*;import io.xeros.model.entity.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.cycleevent.*;import io.xeros.content.combat.Hitmark;
/** Private entry points for the solo edition. Sire respiratory phase, stun windows, adds, poison pools and a dodgeable explosion. */
public final class SoloBossEncounters {
 private SoloBossEncounters(){}
 public static boolean canEnter(Player p){if(p==null||p.isDead||p.getHealth().getCurrentHealth()<=0||p.isDisconnected())return false;if(p.getInstance()!=null||!p.getUtilityMagic().canInteract()){p.sendMessage("Saia da atividade atual antes de entrar em outro boss: ::solo home.");return false;}return true;}
 public static void enter(Player p,boolean sire){if(!canEnter(p))return;Arena a=new Arena(p,sire);}
 public static final class Arena extends InstancedArea{
  private final Player owner;private final boolean sire;private final NPC boss;private int organs,ticks,stunTicks,headDamage;private boolean adds,exploded;
  public Arena(Player p,boolean sire){super(InstanceConfiguration.CLOSE_ON_EMPTY,sire?new Boundary(2960,4750,3055,4860):new Boundary(3460,9460,3545,9535));this.owner=p;this.sire=sire;add(p);int x=sire?3038:3510,y=sire?4767:9496;p.moveTo(new Position(x,y,getHeight()));boss=new NPC(sire?5890:963,new Position(x+2,y,getHeight())){@Override public boolean canBeAttacked(Entity e){return super.canBeAttacked(e);}@Override public boolean canBeDamaged(Entity e){return super.canBeDamaged(e);}@Override public int modifyDamage(Player p,int damage){if(Arena.this.sire&&organs<4){int spell=p.oldSpellId;if(spell>=0&&spell<io.xeros.content.combat.magic.CombatSpellData.MAGIC_SPELLS.length){int button=io.xeros.content.combat.magic.CombatSpellData.MAGIC_SPELLS[spell][0];if(button==13023||button==12999&&Math.random()<.75||button==13011&&Math.random()<.5||button==12987&&Math.random()<.25)stun();}if(stunTicks<=0&&(headDamage+=Math.max(0,damage))>=50)stun();return 0;}return super.modifyDamage(p,damage);}};add(boss);boss.maxHit=31;boss.spawnedBy=p.getIndex();boss.getBehaviour().setRespawn(false);
   if(sire){boss.getHealth().setMaximumHealth(400);boss.getHealth().reset();boss.getBehaviour().setAggressive(false);boss.setInvisible(false);for(int i=0;i<4;i++){final Arena arena=this;NPC lung=new NPC(5914,new Position(x+(i%2==0?-3:5),y+3+(i/2)*4,getHeight())){@Override public boolean canBeAttacked(Entity e){return stunTicks>0&&super.canBeAttacked(e);}@Override public boolean canBeDamaged(Entity e){return stunTicks>0&&super.canBeDamaged(e);}@Override public void onDeath(){super.onDeath();arena.organDead();}};lung.getHealth().setMaximumHealth(50);lung.getHealth().reset();lung.getBehaviour().setRespawn(false);lung.getBehaviour().setAggressive(false);add(lung);}p.sendMessage("Abyssal Sire solo: atordoe o boss com Shadow spells ou 50 de dano acumulado; destrua os Respiratory systems durante o atordoamento.");}
   CycleEventHandler.getSingleton().addEvent(this,new CycleEvent(){public void execute(CycleEventContainer c){if(!active()){c.stop();return;}if(sire)step();}},1);
  }
  private boolean active(){return !isDisposed()&&owner.getInstance()==this&&!owner.isDead&&!owner.isDisconnected()&&owner.getHealth().getCurrentHealth()>0;}
  private void organDead(){if(++organs==4){boss.setInvisible(false);boss.getBehaviour().setAggressive(true);boss.setPlayerAttackingIndex(owner.getIndex());owner.sendMessage("Os Respiratory systems foram destruidos. Abyssal Sire esta vulneravel!");}}
  private void stun(){stunTicks=50;headDamage=0;owner.sendMessage("Abyssal Sire atordoado: ataque os Respiratory systems!");}
  private void step(){if(stunTicks>0)stunTicks--;if(organs<4||boss.isDead()||boss.isUnregister()||boss.getHealth().getCurrentHealth()<=0)return;ticks++;if(ticks%12==0){final Position pool=owner.getPosition();owner.getPA().stillGfx(1275,pool.getX(),pool.getY(),pool.getHeight(),0);CycleEventHandler.getSingleton().addEvent(this,new CycleEvent(){int left=5;public void execute(CycleEventContainer c){if(!active()||boss.isDead()||boss.isUnregister()||--left<0){c.stop();return;}if(owner.getPosition().withinDistance(pool,1))owner.appendDamage(boss,8,Hitmark.HIT);}},2);}
   if(!adds&&boss.getHealth().getCurrentHealth()<=200){adds=true;for(int i=0;i<2;i++){NPC n=NPCSpawning.spawnNpc(this,5916,boss.absX+i,boss.absY-1,getHeight(),0,8);n.spawnedBy=owner.getIndex();n.getBehaviour().setRespawn(false);n.getBehaviour().setAggressive(true);n.setPlayerAttackingIndex(owner.getIndex());CycleEventHandler.getSingleton().addEvent(this,new CycleEvent(){public void execute(CycleEventContainer c){if(active()&&!n.isDead()&&!n.isUnregister()){n.requestTransform(5917);n.maxHit=15;}c.stop();}},20);}}
   if(!exploded&&boss.getHealth().getCurrentHealth()<=100){exploded=true;owner.moveTo(new Position(boss.getX(),boss.getY()-2,getHeight()));final Position danger=owner.getPosition();owner.sendMessage("Abyssal Sire prepara uma explosao. Afaste-se!");CycleEventHandler.getSingleton().addEvent(this,new CycleEvent(){public void execute(CycleEventContainer c){if(active()&&!boss.isDead()&&!boss.isUnregister()&&owner.getPosition().withinDistance(danger,2))owner.appendDamage(boss,30,Hitmark.HIT);c.stop();}},5);}
  }
  @Override public void onDispose(){CycleEventHandler.getSingleton().stopEvents(this);}
 }
}
